{"command": "mkdir -p /tmp/h && cat <<'PYEOF' > /tmp/h/harness.py
import pty, os, sys, time, select, termios, fcntl, struct, re, json

class Screen:
    def __init__(self, rows, cols):
        self.rows=rows; self.cols=cols
        self.grid=[[(' ',()) for _ in range(cols)] for _ in range(rows)]
        self.cx=0; self.cy=0; self.alt=False; self.cursor_visible=True; self.raw=[]
        self.style=()
    def put(self,ch):
        if self.cy<self.rows and self.cx<self.cols:
            self.grid[self.cy][self.cx]=(ch,self.style)
        self.cx+=1
    def feed(self, data):
        self.raw.append(data)
        i=0; n=len(data)
        while i<n:
            c=data[i]
            if c=='\x1b':
                m=re.match(r'\x1b\[([0-9;?]*)([A-Za-z])', data[i:])
                if m:
                    params=m.group(1); cmd=m.group(2)
                    self.csi(params,cmd)
                    i+=m.end(); continue
                m2=re.match(r'\x1b([=>NMc78])', data[i:])
                if m2:
                    c2=m2.group(1)
                    if c2=='7': self.save=(self.cx,self.cy)
                    elif c2=='8': self.cx,self.cy=getattr(self,'save',(0,0))
                    i+=m2.end(); continue
                i+=1; continue
            elif c=='\r': self.cx=0; i+=1; continue
            elif c=='\n':
                self.cy+=1
                if self.cy>=self.rows: self.cy=self.rows-1
                i+=1; continue
            elif c=='\b': self.cx=max(0,self.cx-1); i+=1; continue
            elif c=='\t':
                self.cx=(self.cx//8+1)*8; i+=1; continue
            elif ord(c)<32: i+=1; continue
            else:
                self.put(c); i+=1; continue
    def csi(self, params, cmd):
        ps=[int(x) if x.isdigit() else 0 for x in params.replace('?','').split(';') if x!='']
        if cmd=='H':
            r=ps[0] if len(ps)>0 else 1
            c=ps[1] if len(ps)>1 else 1
            self.cy=r-1; self.cx=c-1
        elif cmd=='J':
            v=ps[0] if ps else 0
            if v==2:
                self.grid=[[(' ',()) for _ in range(self.cols)] for _ in range(self.rows)]
        elif cmd=='K':
            v=ps[0] if ps else 0
            for x in range(self.cx if v==0 else 0, self.cols if v==0 else self.cx+1):
                self.grid[self.cy][x]=(' ',())
        elif cmd=='m':
            if params=='' or params=='0': self.style=()
            else: self.style=self.parse_sgr(params)
        elif cmd=='A': self.cy=max(0,self.cy-(ps[0] if ps else 1))
        elif cmd=='B': self.cy=min(self.rows-1,self.cy+(ps[0] if ps else 1))
        elif cmd=='C': self.cx=min(self.cols-1,self.cx+(ps[0] if ps else 1))
        elif cmd=='D': self.cx=max(0,self.cx-(ps[0] if ps else 1))
        elif cmd=='h':
            if '1049' in params: self.alt=True
            if '25' in params: self.cursor_visible=True
        elif cmd=='l':
            if '1049' in params: self.alt=False
            if '25' in params: self.cursor_visible=False
    def parse_sgr(self, params):
        # returns tuple of sgr codes list
        return tuple(params.split(';'))
    def text(self):
        return '\n'.join(''.join(ch for ch,_ in row).rstrip() for row in self.grid)
    def styled(self):
        out=[]
        for row in self.grid:
            parts=[]; cur=None
            for ch,st in row:
                if ch==' ' and st==() : 
                    if cur: parts.append(cur); cur=None
                    # skip trailing? keep
                    cur=cur or None
                if st!=cur:
                    if cur: parts.append(cur)
                    cur=st
                if cur is not None and (ch!=' ' or st!=()):
                    pass
            out.append(row)
        return None

def spawn(binary, args, rows, cols, env=None):
    pid, fd = pty.fork()
    if pid == 0:
        if env:
            for k,v in env.items(): os.environ[k]=v
        os.execv(binary, [binary]+args)
        os._exit(1)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    return pid, fd

def read_until(fd, timeout=1.0, quiet=0.25):
    out=b""; t0=time.time(); last=time.time()
    while time.time()-t0 < timeout:
        r,_,_=select.select([fd],[],[],0.05)
        if r:
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            out+=d; last=time.time()
        elif time.time()-last>quiet: break
    return out

def keys(fd, keylist, delay=0.3):
    for k in keylist:
        os.write(fd, k)
        time.sleep(delay)

