COLS=int(sys.argv[3]) if len(sys.argv)>3 else 40
ARGS=sys.argv[4].split() if len(sys.argv)>4 else []
KEYS=json.loads(sys.argv[5]) if len(sys.argv)>5 else []
DELAY=float(sys.argv[6]) if len(sys.argv)>6 else 0.3
pid,fd=spawn(BIN,ARGS,ROWS,COLS)
s=Screen(ROWS,COLS)
d=read_until(fd,1.0)
s.feed(d.decode('utf-8','replace'))
print("=== initial ===")
print(s.text())
for k in KEYS:
    os.write(fd,k.encode()); time.sleep(DELAY)
    d=read_until(fd,0.6,0.2)
    s.feed(d.decode('utf-8','replace'))
    print("=== after %r ===" % k)
    print(s.text())
