d=read_until(fd,0.6,0.2); s.feed(d.decode('utf-8','replace'))
print("=== after ESC ===")
print(s.text())
print("=== RAWTAIL ===")
print(s.raw[-1].encode('unicode_escape').decode() if s.raw else '')
try: os.kill(pid,9)
except Exception: pass
