        self.fg=None; self.bg=None; self.attrs=set()
        self.alt=False; self.cursor_visible=True
        self.save=None
        self.raw=[]
    def style(self):
        return (self.fg,self.bg,tuple(sorted(self.attrs)))
    def put(self,ch,w=1):
        if 0<=self.cy<self.rows and 0<=self.cx<self.cols:
            self.grid[self.cy][self.cx]=(ch,self.style())
        self.cx+=w
