// Command line option parsing, replicating the behaviour (incl. error strings)
// of the `getopts` crate as used by the original program.

#[derive(Clone, Copy, PartialEq)]
pub enum HasArg { Yes, No }

pub struct OptDef {
    pub short: Option<char>,
    pub long: &'static str,
    pub has_arg: HasArg,
    pub argname: &'static str,
    pub desc: &'static str,
}

pub const OPTS: &[OptDef] = &[
    OptDef { short: Some('d'), long: "default", has_arg: HasArg::Yes, argname: "TEXT", desc: "text inserted into the textfield on startup" },
    OptDef { short: Some('o'), long: "out-file", has_arg: HasArg::Yes, argname: "FILE", desc: "write final command to file" },
    OptDef { short: None, long: "in-file", has_arg: HasArg::Yes, argname: "FILE", desc: "read initial command from file" },
    OptDef { short: None, long: "config-reference", has_arg: HasArg::No, argname: "", desc: "print out the default configuration file" },
    OptDef { short: Some('r'), long: "raw-mode", has_arg: HasArg::No, argname: "", desc: "keep linebreaks in finished command when closing" },
    OptDef { short: None, long: "no-isolation", has_arg: HasArg::No, argname: "", desc: "disable isolation. This will run the commands directly on your system, without protection. Take care." },
    OptDef { short: Some('h'), long: "help", has_arg: HasArg::No, argname: "", desc: "print this help menu" },
];

#[derive(Default)]
pub struct Matches {
    pub default: Option<String>,
    pub out_file: Option<String>,
    pub in_file: Option<String>,
    pub config_reference: bool,
    pub raw_mode: bool,
    pub no_isolation: bool,
    pub help: bool,
    pub free: Vec<String>,
}

fn find_long(name: &str) -> Option<usize> {
    OPTS.iter().position(|o| o.long == name)
}
fn find_short(c: char) -> Option<usize> {
    OPTS.iter().position(|o| o.short == Some(c))
}

pub fn parse<I: IntoIterator<Item = String>>(args: I, prog: &str) -> Result<Matches, String> {
    let argv: Vec<String> = args.into_iter().collect();
    let mut counts = vec![0usize; OPTS.len()];
    let mut values: Vec<Option<String>> = vec![None; OPTS.len()];
    let mut free: Vec<String> = Vec::new();
    let mut it = argv.iter();
    while let Some(cur) = it.next() {
        if !(cur.len() > 1 && cur.starts_with('-')) {
            free.push(cur.clone());
            continue;
        }
        if cur == "--" {
            free.extend(it.cloned());
            break;
        }
        let mut i_arg: Option<String> = None;
        let mut names: Vec<(usize, String)> = Vec::new(); // (opt index, display name)
        let bytes: Vec<char> = cur.chars().collect();
        if bytes[1] == '-' {
            let tail: String = bytes[2..].iter().collect();
            let mut parts = tail.splitn(2, '=');
            let name = parts.next().unwrap_or("").to_string();
            if let Some(rest) = parts.next() {
                i_arg = Some(rest.to_string());
            }
            match find_long(&name) {
                Some(i) => names.push((i, name.clone())),
                None => return Err(format!("Unrecognized option: '{}'", name)),
            }
        } else {
            let mut ci = 1;
            while ci < bytes.len() {
                let ch = bytes[ci];
                match find_short(ch) {
                    Some(i) => {
                        if OPTS[i].has_arg == HasArg::Yes {
                            names.push((i, ch.to_string()));
                            let rest: String = bytes[ci + 1..].iter().collect();
                            if !rest.is_empty() {
                                i_arg = Some(rest);
                            }
                            ci = bytes.len();
                            continue;
                        } else {
                            names.push((i, ch.to_string()));
                        }
                    }
                    None => return Err(format!("Unrecognized option: '{}'", ch)),
                }
                ci += 1;
            }
        }
        for (i, _n) in names.iter() {
            let def = &OPTS[*i];
            if def.has_arg == HasArg::No {
