// A small TOML parser reproducing the diagnostics of the TOML implementation
// used by the original program.

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Str(String),
    Bool(bool),
    Int(i64),
    Float(f64),
    Datetime(String),
    Array(Vec<Value>),
    Table(Table),
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct Table {
    pub pairs: Vec<(String, Value)>,
}

impl Table {
    pub fn get(&self, key: &str) -> Option<&Value> {
        self.pairs.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    }
    pub fn get_str(&self, key: &str) -> Option<&str> {
        match self.get(key) {
            Some(Value::Str(s)) => Some(s.as_str()),
            _ => None,
        }
    }
    pub fn get_bool(&self, key: &str) -> Option<bool> {
        match self.get(key) {
            Some(Value::Bool(b)) => Some(*b),
            _ => None,
        }
    }
    pub fn get_int(&self, key: &str) -> Option<i64> {
        match self.get(key) {
            Some(Value::Int(i)) => Some(*i),
            _ => None,
        }
    }
    pub fn get_table(&self, key: &str) -> Option<&Table> {
        match self.get(key) {
            Some(Value::Table(t)) => Some(t),
            _ => None,
        }
    }
    pub fn get_str_array(&self, key: &str) -> Option<Vec<String>> {
        match self.get(key) {
            Some(Value::Array(a)) => {
                let mut out = Vec::new();
                for v in a.iter() {
                    match v {
                        Value::Str(s) => out.push(s.clone()),
                        _ => return None,
                    }
                }
                Some(out)
            }
            _ => None,
        }
    }
    fn insert(&mut self, key: String, val: Value) -> bool {
        if self.pairs.iter().any(|(k, _)| *k == key) {
            return false;
        }
        self.pairs.push((key, val));
        true
    }
}

#[derive(Debug, Clone)]
pub struct TError {
    pub pos: usize,
    pub line: usize,
    pub col: usize,
    pub line_text: String,
    pub msg: String,
}

impl std::fmt::Display for TError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "TOML parse error at line {}, column {}\n  |\n{} | {}\n  | {}^\n{}",
            self.line,
            self.col,
            self.line,
            self.line_text,
            " ".repeat(self.col.saturating_sub(1)),
            self.msg
        )
    }
}
impl std::fmt::Debug for TError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Display::fmt(self, f)
    }
}
impl std::error::Error for TError {}

struct P<'a> {
    s: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn eof(&self) -> bool {
        self.i >= self.s.len()
    }
    fn peek(&self) -> u8 {
        if self.eof() {
            0
        } else {
            self.s[self.i]
        }
    }
    fn at(&self, k: usize) -> u8 {
        if self.i + k >= self.s.len() {
            0
        } else {
            self.s[self.i + k]
        }
    }
    fn skip_ws(&mut self) {
        while !self.eof() && (self.s[self.i] == b' ' || self.s[self.i] == b'\t') {
            self.i += 1;
        }
    }
    fn skip_ws_nl_comments(&mut self) {
        loop {
            if self.eof() {
                return;
            }
            match self.s[self.i] {
                b' ' | b'\t' | b'\n' | b'\r' => self.i += 1,
                b'#' => {
                    while !self.eof() && self.s[self.i] != b'\n' {
                        self.i += 1;
                    }
                }
                _ => return,
            }
        }
    }
    fn linecol(&self, pos: usize) -> (usize, usize, String) {
        let mut line = 1usize;
        let mut col = 1usize;
        let mut line_start = 0usize;
        for k in 0..pos.min(self.s.len()) {
            if self.s[k] == b'\n' {
                line += 1;
                col = 1;
                line_start = k + 1;
            } else {
                col += 1;
            }
        }
        let mut end = line_start;
        while end < self.s.len() && self.s[end] != b'\n' {
            end += 1;
        }
        let text = String::from_utf_lossy(&self.s[line_start..end]).to_string();
        (line, col, text)
    }
    fn err(&self, pos: usize, msg: String) -> TError {
        let (line, col, text) = self.linecol(pos);
        TError { pos, line, col, line_text: text, msg }
    }
    // ---------- values ----------
    fn parse_value(&mut self) -> Result<Value, TError> {
        if self.eof() {
            return Err(self.err(self.i, String::new()));
        }
        match self.peek() {
            b'"' => self.parse_basic_string().map(Value::Str),
            b'\'' => self.parse_literal_string().map(Value::Str),
            b'[' => self.parse_array(),
            b'{' => self.parse_inline_table(),
            _ => {
                if self.starts_with("true") {
                    self.i += 4;
                    return Ok(Value::Bool(true));
                }
                if self.starts_with("false") {
                    self.i += 5;
                    return Ok(Value::Bool(false));
                }
                if let Some(v) = self.try_number_or_datetime() {
                    return Ok(v);
                }
                let msg = if self.i == self.s.len() {
                    String::new()
                } else if self.i + 1 == self.s.len() {
                    "invalid string".to_string()
                } else {
                    "invalid string\nexpected `\"`, `'`".to_string()
                };
                Err(self.err(self.i, msg))
            }
        }
    }
    fn starts_with(&self, pat: &str) -> bool {
        self.s[self.i..].starts_with(pat.as_bytes())
    }
    fn parse_basic_string(&mut self) -> Result<String, TError> {
        // multi-line?
        if self.starts_with("\"\"\"") {
            self.i += 3;
            // trim first immediate newline
            if self.peek() == b'\n' {
                self.i += 1;
            } else if self.peek() == b'\r' && self.at(1) == b'\n' {
                self.i += 2;
            }
            let mut out = String::new();
            loop {
                if self.eof() {
                    return Err(self.err(self.i, "invalid multiline basic string".to_string()));
                }
                if self.starts_with("\"\"\"") {
                    self.i += 3;
                    while self.peek() == b'"' {
                        out.push('"');
                        self.i += 1;
                    }
                    return Ok(out);
                }
                if self.peek() == b'\\' {
                    self.i += 1;
                    let c = self.peek();
                    match c {
                        b'\n' | b'\r' | b' ' | b'\t' => {
                            while !self.eof()
                                && (self.s[self.i] == b'\n'
                                    || self.s[self.i] == b'\r'
                                    || self.s[self.i] == b' '
                                    || self.s[self.i] == b'\t')
                            {
                                self.i += 1;
                            }
                        }
                        _ => {
                            let ch = self.escape_char()?;
                            out.push(ch);
                        }
                    }
                    continue;
                }
                let ch = self.char_here();
                if ch == '\n' {
                    return Err(self.err(self.i, "invalid multiline basic string".to_string()));
                }
                out.push(ch);
                self.i += ch.len_utf8();
            }
        }
        self.i += 1; // opening quote
        let mut out = String::new();
        loop {
            if self.eof() {
                return Err(self.err(self.i, "invalid basic string".to_string()));
            }
            let c = self.s[self.i];
            if c == b'"' {
                self.i += 1;
                return Ok(out);
            }
            if c == b'\n' {
                return Err(self.err(self.i, "invalid basic string".to_string()));
            }
            if c == b'\\' {
                self.i += 1;
                let ch = self.escape_char()?;
                out.push(ch);
                continue;
            }
            let ch = self.char_here();
            out.push(ch);
            self.i += ch.len_utf8();
        }
    }
    fn escape_char(&mut self) -> Result<char, TError> {
        if self.eof() {
            return Err(self.err(self.i, "invalid basic string".to_string()));
        }
        let c = self.s[self.i];
        self.i += 1;
        let ch = match c {
            b'b' => '\u{8}',
            b't' => '\t',
            b'n' => '\n',
            b'f' => '\u{c}',
            b'r' => '\r',
            b'"' => '"',
            b'\\' => '\\',
            b'u' | b'U' => {
                let n = if c == b'u' { 4 } else { 8 };
                let mut v: u32 = 0;
                for _ in 0..n {
                    if self.eof() {
                        return Err(self.err(self.i, "invalid basic string".to_string()));
                    }
                    let d = self.s[self.i];
                    let hv = match d {
                        b'0'..=b'9' => (d - b'0') as u32,
                        b'a'..=b'f' => (d - b'a' + 10) as u32,
                        b'A'..=b'F' => (d - b'A' + 10) as u32,
                        _ => {
                            return Err(self.err(self.i, "invalid basic string".to_string()));
                        }
                    };
                    v = v * 16 + hv;
                    self.i += 1;
                }
                match char::from_u32(v) {
                    Some(ch) => ch,
                    None => {
                        return Err(self.err(self.i, "invalid basic string".to_string()));
                    }
                }
            }
            _ => {
                return Err(self.err(self.i, "invalid basic string".to_string()));
            }
        };
        Ok(ch)
    }
    fn char_here(&self) -> char {
        let rest = &self.s[self.i..];
        let st = String::from_utf_lossy(rest);
        st.chars().next().unwrap_or('\u{fffd}')
    }
    fn parse_literal_string(&mut self) -> Result<String, TError> {
        if self.starts_with("'''") {
            self.i += 3;
            if self.peek() == b'\n' {
                self.i += 1;
            } else if self.peek() == b'\r' && self.at(1) == b'\n' {
                self.i += 2;
            }
            let mut out = String::new();
            loop {
                if self.eof() {
                    return Err(self.err(self.i, "invalid multiline literal string".to_string()));
                }
                if self.starts_with("'''") {
                    self.i += 3;
                    while self.peek() == b'\'' {
                        out.push('\'');
                        self.i += 1;
                    }
                    return Ok(out);
                }
                let ch = self.char_here();
                out.push(ch);
                self.i += ch.len_utf8();
            }
        }
        self.i += 1;
        let mut out = String::new();
        loop {
            if self.eof() {
                return Err(self.err(self.i, "invalid literal string".to_string()));
            }
            let c = self.s[self.i];
            if c == b'\'' {
                self.i += 1;
                return Ok(out);
            }
            if c == b'\n' {
                return Err(self.err(self.i, "invalid literal string".to_string()));
            }
            let ch = self.char_here();
            out.push(ch);
            self.i += ch.len_utf8();
        }
    }
    fn parse_array(&mut self) -> Result<Value, TError> {
        let arr_err = |p: &P, pos: usize| {
            p.err(pos, "invalid array\nexpected `]`".to_string())
        };
        self.i += 1; // '['
        let mut items: Vec<Value> = Vec::new();
        loop {
            self.skip_ws_nl_comments();
            if self.eof() {
                return Err(arr_err(self, self.i));
            }
            if self.peek() == b']' {
                self.i += 1;
                return Ok(Value::Array(items));
            }
            let v = match self.parse_value() {
                Ok(v) => v,
                Err(e) => return Err(arr_err(self, e.pos)),
            };
            items.push(v);
            self.skip_ws_nl_comments();
            if self.eof() {
                return Err(arr_err(self, self.i));
            }
            match self.peek() {
                b',' => {
                    self.i += 1;
                }
                b']' => {
                    self.i += 1;
                    return Ok(Value::Array(items));
                }
                _ => return Err(arr_err(self, self.i)),
            }
        }
    }
    fn parse_inline_table(&mut self) -> Result<Value, TError> {
        self.i += 1; // '{'
        let mut t = Table::default();
        loop {
            self.skip_ws();
            if self.eof() {
                return Err(self.err(self.i, "invalid inline table\nexpected `}`".to_string()));
            }
            if self.peek() == b'}' {
                self.i += 1;
                return Ok(Value::Table(t));
            }
            let (key, kpos) = match self.parse_key_part() {
                Ok(v) => v,
                Err(e) => {
                    return Err(self.err(e.pos, "invalid inline table\nexpected `}`".to_string()))
                }
            };
            self.skip_ws();
            if self.peek() != b'=' {
                return Err(self.err(self.i, "invalid inline table\nexpected `}`".to_string()));
            }
            self.i += 1;
            self.skip_ws();
            let v = match self.parse_value() {
                Ok(v) => v,
                Err(e) => {
                    return Err(self.err(e.pos, "invalid inline table\nexpected `}`".to_string()))
                }
            };
            if !t.insert(key, v) {
                return Err(self.err(kpos, "duplicate key".to_string()));
            }
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.i += 1;
                }
                b'}' => {
                    self.i += 1;
                    return Ok(Value::Table(t));
                }
                _ => {
                    return Err(self.err(self.i, "invalid inline table\nexpected `}`".to_string()))
                }
            }
        }
    }
    fn try_number_or_datetime(&mut self) -> Option<Value> {
        let start = self.i;
        // date-time detection: digits, '-' , ':' etc
        let mut j = self.i;
        let mut is_date = false;
        while j < self.s.len() {
            let c = self.s[j];
            if c.is_ascii_digit() || c == b'-' || c == b':' || c == b'.' || c == b'+' || c == b'T'
                || c == b't' || c == b'Z' || c == b'z' || (c == b' ' && j + 1 < self.s.len() && self.s[j + 1].is_ascii_digit() && self.s[j] != b'-' && self.s[j] != b'.')
            {
                if c == b'-' && j > start && self.s[j - 1].is_ascii_digit() {
                    is_date = true;
                }
                if c == b':' {
                    is_date = true;
                }
                j += 1;
            } else {
                break;
            }
        }
        if is_date && j > start {
            let text = String::from_utf_lossy(&self.s[start..j]).to_string();
            self.i = j;
            return Some(Value::Datetime(text));
        }
        // number
        let mut j = self.i;
        if j < self.s.len() && (self.s[j] == b'+' || self.s[j] == b'-') {
            j += 1;
        }
        let mut is_float = false;
        let mut digits = 0;
        while j < self.s.len() {
            let c = self.s[j];
            if c.is_ascii_digit() || c == b'_' {
                digits += 1;
                j += 1;
            } else if c == b'.' {
                is_float = true;
                j += 1;
            } else if c == b'e' || c == b'E' {
                is_float = true;
                j += 1;
                if j < self.s.len() && (self.s[j] == b'+' || self.s[j] == b'-') {
                    j += 1;
                }
            } else if c == b'x' || c == b'o' || c == b'b' {
                j += 1;
            } else if c == b'i' || c == b'n' {
                // inf / nan
                j += 1;
            } else {
                break;
            }
        }
        if digits == 0 {
            // inf / nan?
            if self.starts_with("inf") {
                self.i += 3;
                return Some(Value::Float(f64::INFINITY));
            }
            if self.starts_with("+inf") {
                self.i += 4;
                return Some(Value::Float(f64::INFINITY));
            }
            if self.starts_with("-inf") {
                self.i += 4;
                return Some(Value::Float(f64::NEG_INFINITY));
            }
            if self.starts_with("nan") || self.starts_with("+nan") || self.starts_with("-nan") {
                let n = if self.peek() == b'n' { 3 } else { 4 };
                self.i += n;
                return Some(Value::Float(f64::NAN));
            }
            return None;
        }
        let text: String = String::from_utf_lossy(&self.s[start..j])
            .chars()
            .filter(|c| *c != '_')
            .collect();
        let val = if is_float {
            match text.parse::<f64>() {
                Ok(f) => Value::Float(f),
                Err(_) => return None,
            }
        } else {
            match text.parse::<i64>() {
                Ok(v) => Value::Int(v),
                Err(_) => {
                    // maybe hex/oct/bin
                    match parse_radix(&text) {
                        Some(v) => Value::Int(v),
                        None => return None,
                    }
                }
            }
        };
        self.i = j;
        Some(val)
    }
    // ---------- keys ----------
    fn parse_key_part(&mut self) -> Result<(String, usize), TError> {
        let start = self.i;
        match self.peek() {
            b'"' => {
                let s = self.parse_basic_string()?;
                Ok((s, start))
            }
            b'\'' => {
                let s = self.parse_literal_string()?;
                Ok((s, start))
            }
            c if is_bare_key_char(c) => {
                let mut end = self.i;
                while end < self.s.len() && is_bare_key_char(self.s[end]) {
                    end += 1;
                }
                let s = String::from_utf_lossy(&self.s[self.i..end]).to_string();
                self.i = end;
                Ok((s, start))
            }
            _ => Err(self.err(start, "invalid key".to_string())),
        }
    }
    fn parse_key_path(&mut self) -> Result<(Vec<String>, usize), TError> {
        let mut keys = Vec::new();
        loop {
            self.skip_ws();
            let (k, pos) = self.parse_key_part()?;
            keys.push(k);
            self.skip_ws();
            if self.peek() == b'.' {
                self.i += 1;
                continue;
            }
            return Ok((keys, pos));
        }
    }
}

fn is_bare_key_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-'
}

fn parse_radix(text: &str) -> Option<i64> {
    let t = text.as_bytes();
    let (radix, digits) = if t.len() > 2 && t[0] == b'0' {
        match t[1] {
            b'x' => (16, &t[2..]),
            b'o' => (8, &t[2..]),
            b'b' => (2, &t[2..]),
            _ => (10, t),
        }
    } else {
        (10, t)
    };
    let s = String::from_utf_lossy(digits);
    if radix == 10 {
        return text.parse::<i64>().ok();
    }
    let neg = s.starts_with('-');
    let body = if neg { &s[1..] } else { s.as_str() };
    let v = i64::from_str_radix(body, radix).ok()?;
    Some(if neg { -v } else { v })
}

pub fn parse(src: &str) -> Result<Table, TError> {
    let mut p = P { s: src.as_bytes(), i: 0 };
    let mut root = Table::default();
    // current table path
    let mut cur_path: Vec<String> = Vec::new();
    let mut defined_tables: Vec<Vec<String>> = Vec::new();
    loop {
        p.skip_ws_nl_comments();
        if p.eof() {
            break;
        }
        if p.peek() == b'[' {
            let hdr_start = p.i;
            let is_array = p.at(1) == b'[';
            p.i += if is_array { 2 } else { 1 };
            let keys = match p.parse_key_path() {
                Ok((k, _)) => k,
                Err(e) => {
                    if e.pos == hdr_start + 1 && e.msg == "invalid key" {
                        return Err(p.err(hdr_start, "invalid table header".to_string()));
                    }
                    let msg = if e.pos + 1 != p.s.len() {
                        format!("invalid table header\nexpected `.`, `]`")
                    } else if e.pos == p.s.len() {
                        format!("invalid table header\nexpected `.`, `]`")
                    } else {
                        format!("invalid table header")
                    };
                    return Err(TError { pos: e.pos, msg, ..e });
                }
            };
            p.skip_ws();
            if is_array {
                if p.peek() != b']' || p.at(1) != b']' {
                    return Err(p.err(
                        p.i,
                        "invalid table header\nexpected `]`".to_string(),
                    ));
                }
                p.i += 2;
            } else {
                if p.peek() != b']' {
                    return Err(p.err(
                        p.i,
                        "invalid table header\nexpected `]`".to_string(),
                    ));
                }
                p.i += 1;
            }
            p.skip_ws();
            if !p.eof() && p.peek() != b'\n' && p.peek() != b'\r' && p.peek() != b'#' {
                return Err(p.err(
                    p.i,
                    "invalid table header\nexpected newline, `#`".to_string(),
                ));
            }
            // check duplicates
            if !is_array {
                let quoted: Vec<String> = keys.iter().map(|k| format!("\"{}\"", k)).collect();
                let qname = quoted.join(".");
                if defined_tables.contains(&keys) {
                    let where_ = if keys.len() == 1 {
                        "in document root".to_string()
                    } else {
                        format!("in table {}", keys[..keys.len() - 1].iter().map(|k| format!("\"{}\"", k)).collect::<Vec<_>>().join("."))
                    };
                    return Err(p.err(
                        hdr_start,
                        format!("invalid table header\nduplicate key `{}` {}", qname, where_),
                    ));
                }
                defined_tables.push(keys.clone());
            }
            cur_path = keys;
            continue;
        }
        // key value pair
        let (keys, kpos) = match p.parse_key_path() {
            Ok(v) => v,
            Err(e) => {
                if e.msg == "invalid key" && e.pos == p.i {
                    return Err(e);
                }
                return Err(TError { msg: "expected `.`, `=`".to_string(), ..e });
            }
        };
        p.skip_ws();
        if p.peek() != b'=' {
            return Err(p.err(p.i, "expected `.`, `=`".to_string()));
        }
        p.i += 1;
        p.skip_ws();
        let val = p.parse_value()?;
        p.skip_ws();
        if !p.eof() && p.peek() != b'\n' && p.peek() != b'\r' && p.peek() != b'#' {
            return Err(p.err(p.i, "expected newline, `#`".to_string()));
        }
        // insert into the current table
        let tbl = get_table_mut(&mut root, &cur_path, true);
        let tbl = match tbl {
            Some(t) => t,
            None => {
                return Err(p.err(kpos, format!("duplicate key `{}`", keys.join("."))));
            }
        };
        // navigate the key path
        let mut t = tbl;
        let mut tpath: Vec<String> = Vec::new();
        for k in keys[..keys.len() - 1].iter() {
            let idx = t.pairs.iter().position(|(kk, _)| kk == k);
            match idx {
                Some(ix) => match &mut t.pairs[ix].1 {
                    Value::Table(sub) => {
                        t = sub;
                        tpath.push(k.clone());
                    }
                    _ => {
                        return Err(p.err(
                            kpos,
                            format!(
                                "duplicate key `{}` {}",
                                k,
                                where_str(&tpath)
                            ),
                        ));
                    }
                },
                None => {
                    t.pairs.push((k.clone(), Value::Table(Table::default())));
                    let ix = t.pairs.len() - 1;
                    match &mut t.pairs[ix].1 {
                        Value::Table(sub) => t = sub,
                        _ => unreachable!(),
                    }
                    tpath.push(k.clone());
                }
            }
        }
        let last = keys.last().unwrap().clone();
        if !t.insert(last, val) {
            return Err(p.err(kpos, format!("duplicate key `{}` {}", last, where_str(&tpath))));
        }
    }
    Ok(root)
}

fn where_str(tpath: &[String]) -> String {
    if tpath.is_empty() {
        "in document root".to_string()
    } else {
        format!("in table {}", tpath.iter().map(|k| format!("\"{}\"", k)).collect::<Vec<_>>().join("."))
    }
}

fn get_table_mut<'t>(root: &'t mut Table, path: &[String], _create: bool) -> Option<&'t mut Table> {
    let mut t = root;
    for k in path.iter() {
        let idx = t.pairs.iter().position(|(kk, _)| kk == k);
        match idx {
            Some(ix) => match &mut t.pairs[ix].1 {
                Value::Table(sub) => t = sub,
                _ => return None,
            },
            None => {
                t.pairs.push((k.clone(), Value::Table(Table::default())));
                let ix = t.pairs.len() - 1;
                match &mut t.pairs[ix].1 {
                    Value::Table(sub) => t = sub,
                    _ => unreachable!(),
                }
            }
        }
    }
    Some(t)
}
