                    path.display()
                ))
            }
        };
        match toml_parse(&content) {
            Ok(t) => Ok(t),
            Err(e) => Err(format!("{}\n in {}", e, rel_path(path))),
        }
    })();
    let table = res.unwrap();
    table
}

pub fn load() -> Config {
    let path = config_path();
    if !path.exists() {
        if let Some(dir) = path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        let _ = std::fs::write(&path, DEFAULT_CONFIG);
    }
    let toml = load_toml(&path);
    let cfg = cfg_from(&toml);
    cfg
}
