            cmd_timeout_millis: 2000,
            highlighting_enabled: true,
            eval_environment: vec!["bash".to_string(), "-c".to_string()],
            finish_hook: None,
            snippets: Vec::new(),
            help_viewers: Vec::new(),
            output_viewers: Vec::new(),
        }
    }
}

fn read_and_parse(path: &std::path::Path) -> Result<Table, String> {
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => {
            return Err(format!(
                "configuration file \"{}\" not found",
                path.display()
            ))
        }
    };
    match toml_parse(&content) {
        Ok(t) => Ok(t),
        Err(e) => Err(format!("{}\n in {}", e, rel_path(path))),
    }
}

fn load_toml(path: &std::path::Path) -> Table {
    let toml = read_and_parse(path);
    let table = {
        toml.unwrap()
    };
    table
}

/// Directory pipr keeps its files in, e.g. ~/.config/pipr
pub fn config_dir() -> std::path::PathBuf {
    if let Ok(x) = std::env::var("XDG_CONFIG_HOME") {
        if !x.is_empty() && x.starts_with('/') {
            return std::path::PathBuf::from(x).join("pipr");
        }
    }
    if let Ok(h) = std::env::var("HOME") {
        if !h.is_empty() {
            return std::path::PathBuf::from(h).join(".config").join("pipr");
        }
    }
    std::path::PathBuf::from("pipr")
}

pub fn config_path() -> std::path::PathBuf {
    config_dir().join("pipr.toml")
}
pub fn history_path() -> std::path::PathBuf {
    config_dir().join("history")
}
pub fn bookmarks_path() -> std::path::PathBuf {
    config_dir().join("bookmarks")
}

/// Path relative to the current working directory (used in error messages).
pub fn rel_path(p: &std::path::Path) -> String {
    let cwd = std::env::current_dir().unwrap_or_default();
    let a: Vec<_> = p.components().map(|c| c.as_os_str().to_owned()).collect();
    let b: Vec<_> = cwd.components().map(|c| c.as_os_str().to_owned()).collect();
    let mut common = 0usize;
    while common < a.len() && common < b.len() && a[common] == b[common] {
        common += 1;
    }
    let mut parts: Vec<String> = Vec::new();
    for _ in common..b.len() {
        parts.push("..".to_string());
    }
    for c in a.iter().skip(common) {
        parts.push(c.to_string_lossy().to_string());
    }
    if parts.is_empty() {
        ".".to_string()
    } else {
        parts.join("/")
    }
}

fn table_pairs(t: &Table) -> Vec<(String, String)> {
    let mut out = Vec::new();
    for (k, v) in t.pairs.iter() {
        if let crate::tomlite::Value::Str(s) = v {
            out.push((k.clone(), s.clone()));
        }
    }
    out
}

fn cfg_from(toml: &Table) -> Config {
    let mut c = Config {
        autoeval_mode_default: false,
        ..Config::default()
    };
