        c.cmdlist_always_show_preview = v;
    }
    if let Some(v) = toml.get_int("cmd_timeout_millis") {
        c.cmd_timeout_millis = v.max(0) as u64;
    }
    if let Some(v) = toml.get_bool("highlighting_enabled") {
        c.highlighting_enabled = v;
    }
    if let Some(v) = toml.get_str_array("eval_environment") {
        c.eval_environment = v;
    }
    if let Some(v) = toml.get_str("finish_hook") {
        c.finish_hook = Some(v.to_string());
    }
    if let Some(t) = toml.get_table("snippets") {
        c.snippets = table_pairs(t);
    }
    if let Some(t) = toml.get_table("help_viewers") {
        c.help_viewers = table_pairs(t);
    }
